protocol UserDAO {
    func find(id: Int64) throws -> User?
}

enum Store { case coreData, remote }

func makeUserDAO(for store: Store, context: NSManagedObjectContext,
                 client: APIClient) -> any UserDAO {
    switch store {
    case .coreData: return CoreDataUserDAO(context: context)
    case .remote:   return RemoteUserDAO(client: client)
    }
}
